    csv_path = os.path.join(os.path.dirname(__file__), "books.csv")
    try:
        with open(csv_path, newline='', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            for row in reader:
                # Case-insensitive genre match, strip whitespace just in case
                if row['genre'].strip().lower() == genre.strip().lower():
                    books.append(row)
    except Exception as e:
        # If file missing or error, return empty result based on version
