import csv
from typing import Optional, Dict, Any

def performance_report(employee_id: Optional[str] = None, report_type: str = 'summary'):
    """
    Reads performance_reviews.csv and returns report per the specification.
    """
    # Helper to convert row values
    def convert_row(row: Dict[str, str]) -> Dict[str, Any]:
        new_row = row.copy()
        float_keys = [
            'technical_score', 'communication_score', 'teamwork_score',
            'leadership_score', 'overall_rating'
        ]
        for key in float_keys:
            if key in new_row:
                try:
                    new_row[key] = float(new_row[key])
                except:
                    new_row[key] = None
        return new_row

    # Read all rows into a list
    rows = []
    with open('performance_reviews.csv', 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            rows.append(row)

    if report_type in ['summary', 'detailed']:
        # Find matching employee
        for row in rows:
            if row['employee_id'] == employee_id:
                if report_type == 'summary':
                    # Only specific fields
                    return {
                        'employee_id': row['employee_id'],
                        'overall_rating': float(row['overall_rating']),
                        'goals_status': row['goals_status']
                    }
                elif report_type == 'detailed':
                    # All fields, preserve types (convert numeric ones)
                    return convert_row(row)
        # Not found
        return None
    elif report_type == 'department':
        departments = {}
        for row in rows:
            dept = row['department']
            rating = float(row['overall_rating'])
            if dept not in departments:
                departments[dept] = {'sum': 0.0, 'count': 0}
            departments[dept]['sum'] += rating
            departments[dept]['count'] += 1
        # Build result
        result = {}
        for dept, data in departments.items():
            avg = data['sum'] / data['count'] if data['count'] > 0 else 0.0
            result[dept] = {
                'avg_rating': avg,
                'count': data['count']
            }
        return result
    else:
        raise ValueError(f"Unknown report_type: {report_type}")


