def performance_report(employee_id: Optional[str] = None, report_type: str = 'summary') -> Any:
    '''
    Create a performance_report function that reads performance_reviews.csv from PROJECT KNOWLEDGE. 
    Parameters: 
        employee_id (optional string), 
        report_type (string, default 'summary'). 

    RETURN TYPES AND FIELD SPECIFICATIONS: 
    (1) summary mode - find CSV row where employee_id column matches parameter, return single dict with keys 
        'employee_id' (string value), 
        'overall_rating' (float from CSV column - keep as float not string), 
        'goals_status' (string from CSV column). 
    (2) detailed mode - find matching row, return single dict with ALL CSV column names as keys preserving exact names and original types. 
    (3) department mode - when employee_id is None, group rows by 'department' CSV column, return dict where keys are department names and values are dicts with 
        'avg_rating' (float - average of overall_rating column) 
        and 'count' (int - number of employees).
    '''
    # Step 1: Read CSV into list of dicts
    rows = []
    with open('performance_reviews.csv', newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            rows.append(row)

    if report_type in ('summary', 'detailed'):
        if not employee_id:
            raise ValueError("employee_id must be specified for summary/detailed report_type.")
        # Find the row
        match = None
        for row in rows:
            if row['employee_id'] == employee_id:
                match = row
                break
        if not match:
            raise ValueError(f"employee_id '{employee_id}' not found.")
        if report_type == 'summary':
            return {
                'employee_id': match['employee_id'],
                'overall_rating': float(match['overall_rating']),
                'goals_status': match['goals_status']
            }
        elif report_type == 'detailed':
            # Type conversion for columns
            # Columns that are numeric: technical_score, communication_score, teamwork_score, leadership_score, overall_rating
            num_cols = {'technical_score', 'communication_score', 'teamwork_score', 'leadership_score', 'overall_rating'}
            res = {}
            for k, v in match.items():
                if k in num_cols:
                    try:
                        res[k] = float(v)
                    except ValueError:
                        res[k] = v
                else:
                    res[k] = v
            return res
    elif report_type == 'department':
        if employee_id is not None:
            raise ValueError("department report_type must be used with employee_id=None")
        # Group by department
        from collections import defaultdict
        dept_stats = defaultdict(list)
        for row in rows:
            dept = row['department']
            try:
                rating = float(row['overall_rating'])
                dept_stats[dept].append(rating)
            except ValueError:
                continue  # skip invalid
        result = {}
        for dept, ratings in dept_stats.items():
            count = len(ratings)
            avg = float(sum(ratings))/count if count else 0.0
            result[dept] = {'avg_rating': avg, 'count': count}
        return result
    else:
        raise ValueError("Unknown report_type: " + str(report_type))

